import networkx as nx
from itertools import combinations
G = nx.circulant_graph(9, [1,2,3])
def is_independent_set(G, nodes):
    for u,v in combinations(nodes,2):
        if G.has_edge(u,v):
            return False
    return True
max_size = 0
for size in range(1,6):
    found = False
    for combo in combinations(range(9), size):
        if is_independent_set(G, combo):
            found = True
            break
    if found:
        max_size = size
        print(f"Found ind set of size {size}")
    else:
        print(f"No ind set of size {size}")
        break
print("Alpha =", max_size)
